--
-- Table structure for table `cases`
--

DROP TABLE IF EXISTS `cases`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cases` (
  `case_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Indian legal case number, e.g. HC/MH/2024/001',
  `case_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Full case title / caption',
  `client_id` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FK: client associated with this case',
  `advocate_id` int unsigned NOT NULL COMMENT 'FK: handling advocate',
  `court` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Full court name',
  `judge` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Presiding judge name',
  `case_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type, e.g. Criminal Appeal, Writ Petition',
  `filing_date` date NOT NULL COMMENT 'Date the case was originally filed',
  `status` enum('Ongoing','Disposed','Adjourned','Stayed','Settled') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Ongoing' COMMENT 'Current status of the case',
  `last_date` date DEFAULT NULL COMMENT 'Date of most recent hearing',
  `upcoming_date` date DEFAULT NULL COMMENT 'Date of next scheduled hearing',
  `next_step` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Brief description of next action',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Internal advocate-only notes',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Record creation timestamp',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Last modification timestamp',
  PRIMARY KEY (`case_no`),
  KEY `idx_case_client_id` (`client_id`),
  KEY `idx_case_advocate_id` (`advocate_id`),
  KEY `idx_case_upcoming` (`upcoming_date`),
  KEY `idx_case_status` (`status`),
  CONSTRAINT `fk_case_advocate` FOREIGN KEY (`advocate_id`) REFERENCES `advocates` (`advocate_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_case_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`client_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Central legal cases table - one row per case';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `cases`
--

LOCK TABLES `cases` WRITE;
/*!40000 ALTER TABLE `cases` DISABLE KEYS */;
