--
-- Table structure for table `expenses`
--

DROP TABLE IF EXISTS `expenses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `expenses` (
  `expense_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `client_id` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FK: client whose case incurred this expense',
  `case_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FK: case the expense is against',
  `advocate_id` int unsigned NOT NULL COMMENT 'FK: advocate who incurred the expense',
  `expense_date` date NOT NULL COMMENT 'Date the expense was incurred',
  `amount` decimal(12,2) NOT NULL COMMENT 'Expense amount in INR',
  `title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Category, e.g. Photocopying, Court Fee',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Optional detailed description',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Record creation timestamp',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Last modification timestamp',
  PRIMARY KEY (`expense_id`),
  KEY `idx_expense_client_id` (`client_id`),
  KEY `idx_expense_case_no` (`case_no`),
  KEY `idx_expense_date` (`expense_date`),
  KEY `fk_expense_advocate` (`advocate_id`),
  CONSTRAINT `fk_expense_advocate` FOREIGN KEY (`advocate_id`) REFERENCES `advocates` (`advocate_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_expense_case` FOREIGN KEY (`case_no`) REFERENCES `cases` (`case_no`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_expense_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`client_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2091 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Advocate expenses incurred per case (photocopying, travel, court fees, etc.)';
/*!40101 SET character_set_client = @saved_cs_client */;

