--
-- Table structure for table `hearings`
--

DROP TABLE IF EXISTS `hearings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hearings` (
  `hearing_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `case_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FK: case this hearing belongs to',
  `hearing_date` date NOT NULL COMMENT 'Scheduled date of the hearing',
  `purpose` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Purpose / step for this hearing',
  `result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Outcome - filled after hearing is completed',
  `next_date` date DEFAULT NULL COMMENT 'Next hearing date set during this hearing',
  `is_completed` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 = upcoming, 1 = completed',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Record creation timestamp',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Last modification timestamp',
  PRIMARY KEY (`hearing_id`),
  KEY `idx_hearing_case_no` (`case_no`),
  KEY `idx_hearing_date` (`hearing_date`),
  KEY `idx_hearing_date_done` (`hearing_date`,`is_completed`),
  CONSTRAINT `fk_hearing_case` FOREIGN KEY (`case_no`) REFERENCES `cases` (`case_no`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3199 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='All scheduled and completed court hearings - powers the calendar feature';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `hearings`
--

LOCK TABLES `hearings` WRITE;
/*!40000 ALTER TABLE `hearings` DISABLE KEYS */;
