/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_update_case_dates_after_hearing` AFTER INSERT ON `hearings` FOR EACH ROW BEGIN
    IF NEW.hearing_date >= CURDATE() AND NEW.is_completed = 0 THEN
        
        UPDATE cases
           SET upcoming_date = NEW.hearing_date,
               next_step     = NEW.purpose
         WHERE case_no = NEW.case_no;
    ELSE
        
        UPDATE cases
           SET last_date = NEW.hearing_date
         WHERE case_no = NEW.case_no;
    END IF;
END */;;
