--
-- Table structure for table `login_sessions`
--

DROP TABLE IF EXISTS `login_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `login_sessions` (
  `session_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `user_type` enum('advocate','client') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Role attempting login',
  `user_ref` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Username (advocate) or client_id (client)',
  `login_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Timestamp of the login attempt',
  `is_success` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = successful, 0 = failed',
  `ip_address` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Optional: client IP (for future networking)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Record creation timestamp',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Last modification timestamp',
  PRIMARY KEY (`session_id`),
  KEY `idx_session_user_ref` (`user_ref`),
  KEY `idx_session_time` (`login_time`)
) ENGINE=InnoDB AUTO_INCREMENT=1251 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Security audit log - every login attempt for both roles';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `login_sessions`
--

