--
-- Table structure for table `payments`
--

DROP TABLE IF EXISTS `payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payments` (
  `payment_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `client_id` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FK: paying client',
  `case_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FK: case the payment is for',
  `advocate_id` int unsigned NOT NULL COMMENT 'FK: advocate who received the payment',
  `payment_date` date NOT NULL COMMENT 'Date payment was received',
  `amount` decimal(12,2) NOT NULL COMMENT 'Amount in INR (no currency symbol stored)',
  `note` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Short description, e.g. Partial retainer',
  `receipt_no` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Auto-generated receipt no: RCP/YYYYMMDD/NNNN',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Record creation timestamp',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Last modification timestamp',
  PRIMARY KEY (`payment_id`),
  UNIQUE KEY `uq_payment_receipt` (`receipt_no`),
  KEY `idx_payment_client_id` (`client_id`),
  KEY `idx_payment_case_no` (`case_no`),
  KEY `idx_payment_date` (`payment_date`),
  KEY `fk_payment_advocate` (`advocate_id`),
  CONSTRAINT `fk_payment_advocate` FOREIGN KEY (`advocate_id`) REFERENCES `advocates` (`advocate_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_payment_case` FOREIGN KEY (`case_no`) REFERENCES `cases` (`case_no`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_payment_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`client_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3094 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='All payments received from clients for legal services';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `payments`
--

