/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_mark_due_paid_on_payment` AFTER INSERT ON `payments` FOR EACH ROW BEGIN
    DECLARE v_due_id INT UNSIGNED DEFAULT NULL;
    
    SELECT due_id
      INTO v_due_id
      FROM pending_dues
     WHERE client_id  = NEW.client_id
       AND case_no    = NEW.case_no
       AND is_paid    = 0
       AND amount_due <= NEW.amount
     ORDER BY created_at DESC
     LIMIT 1;
    
    IF v_due_id IS NOT NULL THEN
        UPDATE pending_dues
           SET is_paid  = 1,
               paid_on  = NEW.payment_date
         WHERE due_id   = v_due_id;
    END IF;
END */;;
DELIMITER ;
