CREATE TABLE `pending_dues` (
  `due_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `client_id` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FK: client who owes',
  `case_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FK: case the due relates to',
  `advocate_id` int unsigned NOT NULL COMMENT 'FK: advocate raising the due',
  `amount_due` decimal(12,2) NOT NULL COMMENT 'Amount outstanding in INR',
  `due_date` date NOT NULL COMMENT 'Payment deadline',
  `description` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'What this due is for',
  `is_paid` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 = unpaid, 1 = paid / cleared',
  `paid_on` date DEFAULT NULL COMMENT 'Date cleared (populated when is_paid = 1)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Record creation timestamp',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Last modification timestamp',
  PRIMARY KEY (`due_id`),
  KEY `idx_due_client_id` (`client_id`),
  KEY `idx_due_case_no` (`case_no`),
  KEY `idx_due_date` (`due_date`),
  KEY `idx_due_is_paid` (`is_paid`),
  KEY `fk_due_advocate` (`advocate_id`),
  CONSTRAINT `fk_due_advocate` FOREIGN KEY (`advocate_id`) REFERENCES `advocates` (`advocate_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_due_case` FOREIGN KEY (`case_no`) REFERENCES `cases` (`case_no`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_due_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`client_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3035 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Outstanding billing lines - amounts owed by clients per case';
